/* Generated by tools/convert.js from frontend/visitor/Guide.html — edit the source, not this file. */
/* HAMDI ITALIE — New Immigrant Guide (spec §4 section 13).
   Questions and rules come from the database (admin-editable). Rules are
   evaluated in the browser; answers and progress stay on this device. The
   result is orientation, never an eligibility decision. */

var GUIDE_KEY = 'hi_guide_v1';

function guideState() {
  try { return JSON.parse(localStorage.getItem(GUIDE_KEY)) || { answers: {}, done: {}, step: 0, finished: false }; }
  catch (e) { return { answers: {}, done: {}, step: 0, finished: false }; }
}
function saveGuide(s) { try { localStorage.setItem(GUIDE_KEY, JSON.stringify(s)); } catch (e) {} }

/** {all:[{q,eq|ne}]} / {any:[...]} — unanswered questions never match. */
function ruleMatches(cond, answers) {
  function one(c) {
    if (!c || !c.q || !(c.q in answers)) return false;
    if ('eq' in c) return answers[c.q] === c.eq;
    if ('ne' in c) return answers[c.q] !== c.ne;
    return false;
  }
  if (cond && cond.always) return true;
  if (cond && Array.isArray(cond.all)) return cond.all.length > 0 && cond.all.every(one);
  if (cond && Array.isArray(cond.any)) return cond.any.some(one);
  return false;
}

function renderGuide() {
  loadData('guide', function () { return api('api_getGuide'); }, function (g) {
    var s = guideState();
    if (s.finished) return guideResults(g, s);
    if (!Object.keys(s.answers).length && !s.started) return guideIntro(g, s);
    guideQuestion(g, s);
  });
}

function guideIntro(g, s) {
  setMain(pageSection(crumbs([{ label: t('nav.guide') }]) +
    '<div class="card stack guide-intro"><span class="icon-badge lg" style="color:var(--accent)">' + icon('cat13') + '</span>' +
    '<h1>' + esc(t('guide.title')) + '</h1><p>' + esc(t('guide.intro')) + '</p>' +
    '<div class="notice small">' + icon('info') + '<span>' + esc(t('guide.disclaimer')) + '</span></div>' +
    '<button class="btn btn-primary" id="g-start">' + esc(t('guide.start')) + icon('arrow', 'flip-rtl') + '</button></div>'));
  $('#g-start').onclick = function () { s.started = true; s.step = 0; saveGuide(s); guideQuestion(g, s); };
}

function guideQuestion(g, s) {
  var qs = g.questions;
  if (!qs.length) { s.finished = true; return guideResults(g, s); }
  var i = Math.min(s.step || 0, qs.length - 1), q = qs[i];
  var opts = q.type === 'single_choice' && q.options.length
    ? q.options.map(function (o) { return { value: o.value, label: tf(o, 'label') || o.value }; })
    : [{ value: 'yes', label: t('guide.yes') }, { value: 'no', label: t('guide.no') }];
  setMain(pageSection(crumbs([{ label: t('nav.guide') }]) +
    '<div class="card stack guide-q">' +
      '<div class="row" style="justify-content:space-between"><span class="small muted">' + esc(tv('guide.step', { n: i + 1, total: qs.length })) + '</span></div>' +
      '<div class="progress" role="progressbar" aria-valuemin="0" aria-valuemax="' + qs.length + '" aria-valuenow="' + i + '"><span style="width:' + Math.round(i / qs.length * 100) + '%"></span></div>' +
      '<h1 class="guide-question">' + esc(tf(q, 'question')) + '</h1>' +
      (tf(q, 'help') ? '<p class="muted">' + esc(tf(q, 'help')) + '</p>' : '') +
      '<div class="guide-options">' + opts.map(function (o) {
        var sel = s.answers[q.key] === o.value;
        return '<button class="btn guide-opt' + (sel ? ' selected' : '') + '" data-v="' + esc(o.value) + '" aria-pressed="' + sel + '">' + esc(o.label) + '</button>';
      }).join('') + '</div>' +
      '<div class="row">' + (i > 0 ? '<button class="btn btn-ghost" id="g-back">' + icon('arrow', 'flip-ltr back-arrow') + esc(t('common.back')) + '</button>' : '') + '</div>' +
    '</div>'));
  $$('.guide-opt').forEach(function (b) {
    b.onclick = function () {
      s.answers[q.key] = b.getAttribute('data-v');
      if (i + 1 >= qs.length) { s.finished = true; s.step = i; }
      else s.step = i + 1;
      saveGuide(s);
      s.finished ? guideResults(g, s) : guideQuestion(g, s);
    };
  });
  if ($('#g-back')) $('#g-back').onclick = function () { s.step = i - 1; saveGuide(s); guideQuestion(g, s); };
}

function guideResults(g, s) {
  var tasks = g.rules.filter(function (r) { return ruleMatches(r.condition, s.answers); });
  var doneCount = tasks.filter(function (r) { return s.done[r.task_key]; }).length;
  setMain(pageSection(crumbs([{ label: t('nav.guide') }]) +
    '<div class="row" style="justify-content:space-between"><h1 style="margin:0">' + esc(t('guide.result')) + '</h1>' +
      '<button class="btn btn-sm" id="g-restart">' + esc(t('guide.restart')) + '</button></div>' +
    '<div class="notice warning">' + icon('alert') + '<span>' + esc(t('guide.disclaimer')) + '</span></div>' +
    (tasks.length ? '<div class="stack"><div class="row" style="justify-content:space-between"><span class="small">' + esc(tv('guide.progress', { done: doneCount, total: tasks.length })) + '</span>' +
      '<span class="small muted">' + esc(t('guide.saved')) + '</span></div>' +
      '<div class="progress"><span style="width:' + Math.round(doneCount / tasks.length * 100) + '%"></span></div></div>' : '') +
    (tasks.length ? '<ol class="tasks">' + tasks.map(function (r, n) {
      var done = !!s.done[r.task_key];
      return '<li class="card task' + (done ? ' done' : '') + '">' +
        '<label class="task-check"><input type="checkbox" data-k="' + esc(r.task_key) + '"' + (done ? ' checked' : '') + '><span class="sr-only">' + esc(t('guide.markDone')) + '</span></label>' +
        '<div class="stack task-body"><div class="row"><span class="task-n">' + (n + 1) + '</span><h3 style="margin:0">' + esc(tf(r, 'title')) + '</h3></div>' +
        (r.depends_on_status ? '<span class="badge warning">' + esc(t('guide.depends')) + '</span>' : '') +
        (tf(r, 'explanation') ? textBlock(tf(r, 'explanation')) : '') +
        (tf(r, 'documents') ? '<div class="small"><strong>' + esc(t('svc.documents')) + ':</strong> ' + esc(tf(r, 'documents')) + '</div>' : '') +
        (tf(r, 'institution') ? '<div class="small"><strong>' + esc(t('guide.institution')) + ':</strong> ' + esc(tf(r, 'institution')) + '</div>' : '') +
        '<div class="row">' +
          (r.service_slug ? '<a class="btn btn-sm" href="#/service/' + encodeURIComponent(r.service_slug) + '">' + esc(t('guide.service')) + '</a>' : '') +
          (r.official_link ? '<a class="btn btn-sm btn-ghost" href="' + esc(safeUrl(r.official_link)) + '" target="_blank" rel="noopener">' + icon('globe') + esc(t('guide.official')) + '</a>' : '') +
        '</div></div></li>';
    }).join('') + '</ol>' : '<div class="card"><p class="muted" style="margin:0">' + esc(t('guide.empty')) + '</p></div>') +
    '<div class="card guide-band"><span class="icon-badge">' + icon('chat') + '</span><div><strong>' + esc(t('svc.request')) + '</strong>' +
      '<p class="muted small" style="margin:0">' + esc(t('cash.text')) + '</p></div>' +
      '<a class="btn btn-accent" href="#/request/colloquio-di-orientamento-per-nuovi-arrivati">' + esc(t('svc.request')) + '</a></div>'));
  $$('.task-check input').forEach(function (cb) {
    cb.onchange = function () {
      if (cb.checked) s.done[cb.getAttribute('data-k')] = true; else delete s.done[cb.getAttribute('data-k')];
      saveGuide(s); guideResults(g, s);
    };
  });
  $('#g-restart').onclick = function () {
    var fresh = { answers: {}, done: {}, step: 0, finished: false, started: true };
    saveGuide(fresh); guideQuestion(g, fresh);
  };
}
